// ===== EDIT THIS LIST =====
// One row per plant: [name, category, origin, editorial_hint, status, wiki_topic (optional)]
// editorial_hint is NOT treated as a fact: the agents only use it if Wikipedia/Tavily confirm it.
// wiki_topic: set it when the common name lands on the wrong Wikipedia page
// (e.g. "Lotus" -> the car brand). Use the scientific name instead.
const PLANT_ROWS = [
  ["Dieffenbachia", "Indoor Plant", "Central and South America", "Chewing its leaves causes temporary inability to speak.", "Toxic"],
  ["Oleander", "Garden Plant", "Mediterranean Basin", "One of the most poisonous plants in the world; all parts are toxic.", "Highly Toxic", "Nerium oleander"],
  ["Aloe Vera", "Medicinal Plant", "Africa", "The gel in its leaves has been used to treat burns and wounds for thousands of years.", "Beneficial", "Aloe vera"],
  ["Snake Plant", "Indoor Plant", "West Africa", "It is one of the rare plants that converts CO2 into oxygen at night.", "Easy Care", "Dracaena trifasciata"],
  ["Lavender", "Medicinal Plant", "Mediterranean", "Its scent calms the nervous system and improves sleep quality.", "Medicinal/Decorative", "Lavandula"],
  ["Monstera Deliciosa", "Indoor Plant", "Mexican Rainforests", "The holes in its leaves allow wind to pass through during storms.", "Popular", "Monstera deliciosa"],
  ["Orchid", "Indoor Plant", "Tropical Regions", "Has the largest plant family and grows on tree bark instead of soil.", "Delicate", "Orchidaceae"],
  ["Rosemary", "Kitchen/Garden", "Mediterranean", "It has been scientifically proven to strengthen memory.", "Edible", "Salvia rosmarinus"],
  ["Poinsettia", "Indoor Plant", "Mexico", "The red parts are not flowers but leaves called bracts.", "Winter Plant"],
  ["Peace Lily", "Indoor Plant", "Americas and Southeast Asia", "Cleans toxins like benzene and formaldehyde from the air.", "Air Purifier", "Spathiphyllum"],
  ["Venus Flytrap", "Exotic Plant", "USA (North Carolina)", "It traps insects touching its leaves in less than half a second.", "Carnivorous", "Venus flytrap"],
  ["Ginkgo Biloba", "Outdoor", "China", "A living fossil from the dinosaur era; can live for 1000 years.", "Ancient", "Ginkgo biloba"]
];

function pick(arr) {
  return arr[(Math.random() * arr.length) | 0];
}

function slugify(s) {
  return String(s).toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '');
}

const sd = $getWorkflowStaticData('global');
sd.plantRotation = sd.plantRotation || { used: [] };
let unused = PLANT_ROWS.filter(p => !sd.plantRotation.used.includes(p[0]));
if (unused.length === 0) { sd.plantRotation.used = []; unused = PLANT_ROWS.slice(); }
const plant = pick(unused);
// The plant is marked as used only at the very end ('Build Package'), so a failed run does not consume it.
// Note: n8n keeps staticData only for production (active) executions, not manual test runs.

// --- Snippets per video (each becomes one narration block + one image) ---
// The lite version always produces 1 chapter.
const chapters = 1;
const snippets = 3;
// -----------------------------------------

// The chapter fact sheet is the script writer's ONLY source, so its length scales with the number of
// snippets (each snippet is 35-45 spoken words and needs its own facts).
const desc_sentences = Math.max(4, snippets * 3);
const desc_min_chars = desc_sentences * 95;

const name       = plant[0];
const category   = plant[1];
const origin     = plant[2];
const hint       = plant[3];
const statusType = plant[4];
const wikiTopic  = plant[5] || plant[0];

const titleTemplates = [
  `Shocking Truth About the ${name}`,
  `${name}: Nature's Secret Miracle`,
  `What is the Secret of the ${name}?`,
  `The Incredible Story of the ${name}`,
  `The Hidden World of the ${name}`,
  `Why the ${name} Baffles Scientists`,
  `Inside the ${name}: A Botanical Mystery`,
  `The Bizarre Biology of the ${name}`,
  `The Secret Life of the ${name}`,
  `How the ${name} Survives the Impossible`,
  `${name}: Nature's Ultimate Survivor`,
  `The Untold Story of the ${name}`,
  `${name}: Nature's Masterpiece`,
  `What They Never Told You About the ${name}`,
  `The Extraordinary Power of the ${name}`,
  `${name}: The Plant That Changed History`
];

const title = pick(titleTemplates);
const caption = `Everything you need to know about the ${name} (${category}). #plants #botany #nature #${slugify(name)}\n\nNote: Visuals and narration in this video are AI-generated. Images are artistic illustrations, not real photographs of the ${name}. For general education only; not medical advice.`;

const video_details =
  `TOPIC:\n- Plant Name: ${name}\n- Wikipedia Topic: ${wikiTopic}\n- Category: ${category}\n- Origin: ${origin}\n- Editorial Hint: ${hint}\n- Status: ${statusType}\n\n` +
  `FORMAT:\n- YouTube Shorts 9:16\n- ${chapters} Chapter(s), ${snippets} Snippet(s)\n- English Narration\n\n` +
  `TONE:\n- Educational, Intriguing, Botanical Documentary Style`;

return [{
  json: {
    plant_key: slugify(name),
    plant_name: name,
    wiki_topic: wikiTopic,
    category: category,
    origin: origin,
    editorial_hint: hint,
    status_type: statusType,
    title,
    caption,
    video_details,
    chapters,
    snippets,
    desc_sentences,
    desc_min_chars
  }
}];

/**
 * Wikipedia Guard — disambiguation, wrong-subject and empty-extract
 * protection, tuned for plants.
 *
 * Expects the MediaWiki extracts API:
 *   /w/api.php?action=query&format=json&prop=extracts|pageprops
 *     &ppprop=disambiguation&explaintext=1&redirects=1&titles=<wiki_topic>
 *
 * Falls back to the old REST summary shape if the URL was not updated.
 */

const MAX_CHARS = 8000;
const MIN_CHARS = 200;

const src = ($input.first() && $input.first().json) ? $input.first().json : {};
const pickJson = $('Pick Plant').first().json;
const wanted = String(pickJson.wiki_topic || pickJson.plant_name || '');

// ---------------------------------------------------------------- 1) Parse
let title = '', extractRaw = '', missing = false, disambigFlag = false, redirectedFrom = '';

if (src.query && src.query.pages) {
  const pages = Array.isArray(src.query.pages)
    ? src.query.pages
    : Object.values(src.query.pages);
  const page = pages[0] || {};

  missing = page.missing !== undefined;
  title = String(page.title || '');
  extractRaw = String(page.extract || '').trim();
  disambigFlag = !!(page.pageprops && page.pageprops.disambiguation !== undefined);

  const redirects = src.query.redirects;
  if (Array.isArray(redirects) && redirects.length) {
    redirectedFrom = String(redirects[0].from || '');
  }
} else {
  title = String(src.title || '');
  extractRaw = typeof src.extract === 'string' ? src.extract.trim() : '';
  disambigFlag = String(src.type || '').toLowerCase().includes('disambiguation');
  missing = src.title === 'Not found.';
}

// ------------------------------------------------- 2) Strip boilerplate tail
// Keep Taxonomy / Description / Uses / Cultivation — that is where the
// compounds, habitats and historical uses live.
const DROP_SECTIONS = [
  'See also', 'References', 'Notes', 'Citations', 'Footnotes',
  'Sources', 'Further reading', 'External links', 'Gallery'
];
for (const section of DROP_SECTIONS) {
  const marker = new RegExp('\\n=+\\s*' + section + '\\s*=+\\s*\\n', 'i');
  const hit = extractRaw.search(marker);
  if (hit > 0) extractRaw = extractRaw.slice(0, hit);
}
extractRaw = extractRaw.replace(/\n{3,}/g, '\n\n').trim();

// -------------------------------------------------------- 3) Budget cutoff
let truncated = false;
if (extractRaw.length > MAX_CHARS) {
  truncated = true;
  let cut = extractRaw.slice(0, MAX_CHARS);
  const para = cut.lastIndexOf('\n\n');
  const sentence = cut.lastIndexOf('. ');
  if (para > MAX_CHARS * 0.6) cut = cut.slice(0, para);
  else if (sentence > MAX_CHARS * 0.6) cut = cut.slice(0, sentence + 1);
  extractRaw = cut.trim();
}

// ------------------------------------------------------- 4) Quality checks
const httpFailed = !!src.error || !!src.httpCode || missing;

const isDisambiguation =
  disambigFlag ||
  /\bmay refer to\b/i.test(extractRaw) ||
  /\bmay also refer to\b/i.test(extractRaw) ||
  /\bcommonly refers to\b/i.test(extractRaw) ||
  (/\bis the name of\b/i.test(extractRaw) && extractRaw.length < 400);

const tooShort = extractRaw.length < MIN_CHARS;

const norm = (s) => String(s)
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();

// Title check is skipped when Wikipedia itself resolved a redirect —
// common names legitimately redirect to scientific names
// (Snake Plant -> Dracaena trifasciata).
const wantedTokens = norm(wanted).split(' ').filter(t => t.length > 2);
const titleNorm = norm(title);
const titleMismatch =
  !redirectedFrom &&
  wantedTokens.length > 0 &&
  !wantedTokens.some(t => titleNorm.includes(t));

// Domain check — the article must actually be about a plant. This is what
// catches "Bird of Paradise" landing on the bird, or "Lotus" on the car.
const BOTANY_TERMS = [
  'plant', 'species', 'genus', 'leaves', 'leaf', 'flower', 'flowering',
  'tree', 'shrub', 'herb', 'herbaceous', 'botanic', 'family', 'native to',
  'cultivat', 'seed', 'fruit', 'root', 'stem', 'perennial', 'annual',
  'evergreen', 'deciduous', 'pollinat', 'foliage', 'vine', 'succulent'
];
const lower = extractRaw.toLowerCase();
const botanyHits = BOTANY_TERMS.filter(t => lower.includes(t)).length;
const wrongDomain = extractRaw.length > 0 && botanyHits < 3;

let status = 'ok';
if (httpFailed) status = 'unavailable';
else if (!extractRaw) status = 'no_extract';
else if (isDisambiguation) status = 'disambiguation';
else if (titleMismatch) status = 'title_mismatch';
else if (wrongDomain) status = 'wrong_domain';
else if (tooShort) status = 'too_short';

const valid = status === 'ok';

// ------------------------------------------------------- 5) Richness signal
const yearCount = (extractRaw.match(/\b1[0-9]{3}\b|\b20[0-9]{2}\b/g) || []).length;

// Binomial scientific names ("Aloe vera", "Nelumbo nucifera") are the
// clearest sign the article carries real botanical substance.
const binomials = (extractRaw.match(/\b[A-Z][a-z]{3,}\s+[a-z]{4,}\b/g) || []).length;

const richness = !valid
  ? 'none'
  : (extractRaw.length > 3000 && binomials >= 3)
    ? 'rich'
    : (extractRaw.length > 1000 && binomials >= 1)
      ? 'moderate'
      : 'thin';

return [{
  json: {
    wiki_valid: valid,
    wiki_status: valid ? 'ok' : ('UNUSABLE (' + status + ')'),
    wiki_title: valid ? title : '',
    wiki_extract: valid ? extractRaw : '',
    wiki_richness: richness,
    wiki_length: valid ? extractRaw.length : 0,
    wiki_binomials: valid ? binomials : 0,
    wiki_year_mentions: valid ? yearCount : 0,
    wiki_botany_hits: botanyHits,
    wiki_truncated: truncated,
    wiki_redirected_from: redirectedFrom
  }
}];

