// Validate the agent output: chapter count, description length, title, image prompt.
var pk = $('Pick Plant').first().json;
var need = Number(pk.chapters);
var minChars = Number(pk.desc_min_chars);
var src = $input.first().json || {};
var chapters = (src.output && src.output.chapters) || [];
var problems = [];
if (!Array.isArray(chapters)) { problems.push('chapters is not an array'); chapters = []; }
if (chapters.length !== need) problems.push('got ' + chapters.length + ' chapters, expected ' + need);
var fixed = chapters.map(function (c, i) {
  var d = String(c.chapter_description || '').replace(/\s+/g, ' ').trim();
  if (!String(c.chapter_title || '').trim()) problems.push('chapter ' + (i + 1) + ': empty title');
  if (d.length < minChars) problems.push('chapter ' + (i + 1) + ': description is ' + d.length + ' chars (min ' + minChars + ')');
  if (String(c.image_prompt || '').trim().length < 20) problems.push('chapter ' + (i + 1) + ': image_prompt missing');
  return Object.assign({}, c, { chapter_number: c.chapter_number || (i + 1), chapter_description: d });
});
return [{ json: { ok: problems.length === 0, problems: problems, output: { chapters: fixed } } }];

// At most 2 retries (3 generations in total). $runIndex = how many times this node ran in this execution.
var p = ($input.first().json.problems || []).join('; ');
if ($runIndex >= 2) throw new Error('Fact Sheet Agent failed validation 3 times: ' + p);
return [{ json: { retry: $runIndex + 1, problems: p } }];

// Lite version: one chapter. Pass its fact sheet to the script writer and
// refuse to continue if it is too thin (otherwise the writer would have to invent facts).
var ch = ($input.first().json.output.chapters || [])[0];
if (!ch) throw new Error('Resolve Chapter: no chapter in the validated output.');
var description = String(ch.chapter_description || '').trim();
var minChars = Number($('Pick Plant').first().json.desc_min_chars) * 0.8;
if (description.length < minChars) {
  throw new Error('Resolve Chapter: fact sheet is only ' + description.length + ' chars - stopping instead of writing an unsourced script.');
}
return [{ json: {
  chapter_number: ch.chapter_number || 1,
  chapter_title: ch.chapter_title,
  chapter_description: description,
  chapter_lesson: ch.chapter_lesson,
  image_prompt: String(ch.image_prompt || '').trim()
} }];

