// Validate the script: fix small issues, regenerate on big ones.
var need = Number($('Pick Plant').first().json.snippets);
var chNo = $('Resolve Chapter').first().json.chapter_number;
var src = $input.first().json || {};
var script = (src.output && src.output.script) || [];
var problems = [];
if (!Array.isArray(script)) { problems.push('script is not an array'); script = []; }
if (script.length !== need) problems.push('got ' + script.length + ' snippets, expected ' + need);
var fixed = script.map(function (s, i) {
  var t = String(s.script_text || '').replace(/\s+/g, ' ').trim();
  var words = t ? t.split(' ').length : 0;
  if (words < 25 || words > 65) problems.push('snippet ' + (i + 1) + ': ' + words + ' words (target 35-45)');
  var ip = String(s.image_prompt || '').replace(/\s+/g, ' ').trim();
  if (ip.length < 25) problems.push('snippet ' + (i + 1) + ': image_prompt missing');
  return { chapter_number: chNo, script_number: i + 1, script_text: t, image_prompt: ip };
});
if (fixed.length) {
  var last = fixed[fixed.length - 1];
  if (!/!$/.test(last.script_text)) last.script_text = last.script_text.replace(/[.?…!\s]+$/, '') + '!';
}
// On the 3rd attempt, accept a script whose ONLY problem is word count (within a hard 18-65 floor/ceiling),
// so the whole run is not wasted when the model keeps returning slightly short snippets.
var soft = false;
if ($runIndex >= 2 && problems.length && fixed.length === need) {
  var lenOnly = problems.every(function (p) { return /words/.test(p); });
  var floorOk = fixed.every(function (f) { var n = f.script_text.split(' ').length; return n >= 18 && n <= 65; });
  if (lenOnly && floorOk) { problems = []; soft = true; }
}
return [{ json: { ok: problems.length === 0, problems: problems, soft_accept: soft, output: { script: fixed } } }];

// At most 2 retries (3 generations in total).
var p = ($input.first().json.problems || []).join('; ');
if ($runIndex >= 2) throw new Error('Script Agent failed validation 3 times: ' + p);
return [{ json: { retry: $runIndex + 1, problems: p } }];

// Final package: one item per snippet with its narration text and image (binary 'data'),
// plus the video title and caption. Matched BY INDEX so the order can never drift.
const pk = $('Pick Plant').first().json;
const ch = $('Resolve Chapter').first().json;
const snippets = $('Split Snippets').all();
const images = $input.all();
if (images.length !== snippets.length) {
  throw new Error('Snippet count (' + snippets.length + ') does not match image count (' + images.length + ')');
}

// Mark the plant as used only now that the run has succeeded.
const sd = $getWorkflowStaticData('global');
sd.plantRotation = sd.plantRotation || { used: [] };
if (!sd.plantRotation.used.includes(pk.plant_name)) sd.plantRotation.used.push(pk.plant_name);

return snippets.map((s, i) => {
  const img = images[i];
  const hasImage = !!(img.binary && img.binary.data);
  return {
    json: {
      plant_name: pk.plant_name,
      video_title: pk.title,
      caption: pk.caption,
      chapter_title: ch.chapter_title,
      script_number: s.json.script_number,
      script_text: s.json.script_text,
      image_prompt: s.json.image_prompt,
      image_ok: hasImage,
      full_narration: snippets.map(x => x.json.script_text).join(' ')
    },
    binary: hasImage ? img.binary : undefined
  };
});
